import{_ as a,o as s,c as e,a2 as t}from"./chunks/framework.CsFjlSKj.js";const k=JSON.parse('{"title":"Advanced Security & Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"containers/7-security-and-advanced.md","filePath":"containers/7-security-and-advanced.md"}'),n={name:"containers/7-security-and-advanced.md"};function o(r,i,l,p,h,c){return s(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="advanced-security-configuration" tabindex="-1">Advanced Security &amp; Configuration <a class="header-anchor" href="#advanced-security-configuration" aria-label="Permalink to &quot;Advanced Security &amp; Configuration&quot;">​</a></h1><p>Running containers locally is simple, but running them securely in production requires dropping capabilities, restricting filesystems, and applying security profiles.</p><h2 id="container-security" tabindex="-1">Container Security <a class="header-anchor" href="#container-security" aria-label="Permalink to &quot;Container Security&quot;">​</a></h2><p>By default, Docker containers run as the <code>root</code> user. This is a massive security risk. While the container is isolated, if a hacker finds a kernel exploit to break out of the container (a &quot;container escape&quot;), they will pop out onto the host machine as the root user.</p><h3 id="_1-dropping-capabilities" tabindex="-1">1. Dropping Capabilities <a class="header-anchor" href="#_1-dropping-capabilities" aria-label="Permalink to &quot;1. Dropping Capabilities&quot;">​</a></h3><p>The Linux Kernel grants the <code>root</code> user specific capabilities (e.g., <code>CAP_SYS_ADMIN</code>, <code>CAP_NET_BIND_SERVICE</code>). You can strip these from a container so that even if the container is running as root, it is completely powerless to modify the host kernel.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Drop ALL root capabilities</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cap-drop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secure-nginx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx:latest</span></span></code></pre></div><h3 id="_2-read-only-root-filesystem" tabindex="-1">2. Read-Only Root Filesystem <a class="header-anchor" href="#_2-read-only-root-filesystem" aria-label="Permalink to &quot;2. Read-Only Root Filesystem&quot;">​</a></h3><p>Hackers need to download malware into your container to execute attacks. If you mount the entire root filesystem of the container as Read-Only, they cannot write anything to disk.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --read-only</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/nginx:/var/cache/nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/run:/var/run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  nginx:latest</span></span></code></pre></div><p><em>(Note: You must map temporary volumes to specific directories the app needs to write to).</em></p><h3 id="_3-apparmor-and-seccomp-profiles" tabindex="-1">3. AppArmor and Seccomp Profiles <a class="header-anchor" href="#_3-apparmor-and-seccomp-profiles" aria-label="Permalink to &quot;3. AppArmor and Seccomp Profiles&quot;">​</a></h3><p>Docker automatically applies a default <code>seccomp</code> profile that disables roughly 44 of the 300+ available Linux system calls, preventing containers from doing things like altering the system clock or loading kernel modules.</p><p>You can apply custom, stricter security profiles:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --security-opt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> seccomp=/path/to/custom-profile.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><h2 id="health-checks" tabindex="-1">Health Checks <a class="header-anchor" href="#health-checks" aria-label="Permalink to &quot;Health Checks&quot;">​</a></h2><p>A container might be &quot;running&quot; (Process ID exists), but the application inside it might be frozen or returning 500 errors.</p><p>Docker allows you to define native Health Checks. The Docker daemon will periodically run a command inside the container to verify the app is actually alive.</p><div class="language-dockerfile vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Inside a Dockerfile</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HEALTHCHECK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --interval=30s --timeout=3s \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> curl -f http://localhost/ || exit 1</span></span></code></pre></div><p>If the <code>curl</code> command fails, Docker marks the container as <code>unhealthy</code>, allowing orchestrators like Docker Swarm or Kubernetes to automatically restart it.</p>`,20)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
